#include <stdio.h>

typedef struct{ 
    enum {Binary, Unary} type;
    union {
        struct{         // Binary
            int left;
            int right;
        };
        struct{         // Unary
            int value;
        };
    };
} Operation;

#define Unary(val) {.type=Unary, .value=val}
#define Binary(l, r) {.type=Binary, .left=l, .right =r}

void print_op(Operation op){
    switch (op.type){
        case Binary:
            printf("%d * %d\n", op.left, op.right);
            break;
        case Unary:
            printf("%d\n", op.value);
            break;
    }
}

int main (void){

    Operation op1 = Binary(5, 6);
    Operation op2 = Unary(3);

    print_op(op1);
    print_op(op2);

    return 0;
}
```

