### C



С помощью библиотечных функций `strol()/stroll()`



```c


#include <stdlib.h>
#include <stdio.h>
#include <errno.h> // для errno
 
int main() {
    char *str = "12345";
    errno = 0; // Сбрасываем errno перед вызовом
    char *endptr;

    long number = strtol(str, &endptr, 10);
 
    // Проверяем возможные ошибки
    if (errno == ERANGE || endptr == str) {
        puts("Unable to convert the string to a number");
    }
    else {
        printf("Result: %ld\n", number);
    } 
    return 0;
}
```


 

 

